def S(n):
    return sum(int(digit) for digit in str(n))

def check_n(n, limit=37):
    for k in range(n, n + limit + 1):
        s_k = S(k)
        if s_k > 0 and s_k % 11 == 0:
            return False, k
    return True, None

# Test the hypothesis based on n near a power of 10
n_test = 9990
is_valid, k_fail = check_n(n_test)

print(f"Testing n = {n_test}")
if is_valid:
    print("Result: Valid (Product is not divisible by 11)")
else:
    print(f"Result: Invalid (S({k_fail}) = {S(k_fail)} is divisible by 11)")

